PENSION_HEADER_COLS = [
    ("名称", 49, 63),
    ("取得価額", 115, 141),
    ("現在価値", 168, 195),
    ("評価損益", 219, 246),
    ("評価損益率", 269, 303),
    ("取得日", 333, 353),
    ("変更", 392, 405),
    ("削除", 438, 451),
]

POINT_HEADER_COLS = [
    ("名称", 21, 34),
    ("種類", 58, 71),
    ("ポイント・マイル数", 101, 161),
    ("換算レート", 181, 215),
    ("現在の価値", 227, 260),
    ("有効期限", 283, 310),
    ("保有金融機関", 335, 375),
    ("変更", 402, 416),
    ("削除", 441, 455),
]


def deposit_header(top: float) -> list[Word]:
    return _header(DEPOSIT_HEADER_COLS, top)


def stock_header(top: float, shift: float = 0.0) -> list[Word]:
    """株式の2行折返しヘッダ（銘柄コ/ード、保有/金融/機関）。"""
    words = _header(STOCK_HEADER_COLS, top, shift)
    words += [w("ード", 25 + shift, 38 + shift, top + 8.5), w("金融", 412 + shift, 426 + shift, top + 8.5)]
    words += [w("機関", 412 + shift, 426 + shift, top + 17.1)]
    return words


def stock_header_vertical(top: float) -> list[Word]:
    """保有金融機関 列が1文字幅まで潰れて縦組みになった株式ヘッダ。

    2026-08-07 の実PDFで観測されたレイアウト。前日比に実値が入って列が広がると、
    可変幅のテキスト列が圧縮され 保/有/金/融/機/関 が1文字ずつ縦に並ぶ。
    """
    cols = [c for c in STOCK_HEADER_COLS if c[0] != "保有"]
    words = _header(cols, top)
    words += [w("ード", 25, 38, top + 8.5)]
    words += [w(ch, 414, 424, top + 8.5 * i) for i, ch in enumerate("保有金融機関")]
    return words


def fund_header(top: float) -> list[Word]:
    return _header(FUND_HEADER_COLS, top)


def pension_header(top: float) -> list[Word]:
    return _header(PENSION_HEADER_COLS, top)


def point_header(top: float) -> list[Word]:
    return _header(POINT_HEADER_COLS, top)


def heading(text: str, top: float) -> list[Word]:
    return [w(text, 14, 61, top)]


def total_line(amount: str, top: float) -> list[Word]:
    # 実PDFでは「合計︓N円」が1単語（︓はNFKCで:に正規化される）
    return [w(f"合計︓{amount}円", 21, 93, top)]


def sample_pages() -> list[list[Word]]:
    """架空データによる3ページのフル文書。

    - 資産総額 320,399円 = 預金3,500 + 株式79,000 + 投信115,999 + 暗号500
      + 年金120,000 + ポイント1,400
    - 検算NG行1件（投信2行目）と unparsed 行1件（ポイント末尾）を含む。
    """
    page1: list[Word] = []
    # セクション開始前のナビ・説明文（ノイズ）
    page1 += [w("ホーム", 36, 63, 69), w("家計簿", 107, 134, 69)]
    page1 += [w("資産内訳", 17, 49, 95), w("資産推移", 60, 92, 95)]
    page1 += [w("資産総額︓", 18, 61, 246), w("320,399円", 64, 124, 246)]
    page1 += [w("資産の内訳", 21, 64, 272)]
    # 内訳サマリー行（3単語なので見出しにならない）
    page1 += [w("預金・現金", 28, 65, 297), w("3,500円", 257, 295, 297), w("1.09%", 364, 388, 297)]
    # 円グラフの二重文字ラベル
    page1 += [w("株株式式現現物物", 172, 204, 475)]
    page1 += [w("((", 187, 190, 478), w("))", 204, 207, 478)]
    # 預金・現金
    page1 += heading("預金・現金", 590)
    page1 += total_line("3,500", 615)
    page1 += deposit_header(640)
    page1 += [
        w("テスト支店", 19, 63, 658), w("普通", 66, 81, 658),
        w("１，２３４円", 159, 192, 658),  # 全角数字・全角カンマ
        w("架空ネット銀", 200, 252, 658),
    ]
    page1 += [w("行", 200, 208, 669)]  # 機関名の折返し断片
    page1 += [
        w("代表口座", 19, 48, 688), w("-", 51, 54, 688), w("豪ドル普通", 57, 94, 688),
        w("4円", 180, 192, 688),  # 小さな残高は機関列に落ちる→補正対象
        w("架空ネット銀", 200, 252, 688),
    ]
    page1 += [w("行", 200, 208, 698)]
    page1 += [w("現金", 19, 34, 717), w("2,262円", 163, 192, 717), w("架空証券", 200, 230, 717)]
    # 株式(現物) — ページを跨ぐセクション
    page1 += heading("株式(現物)", 740)
    page1 += total_line("79,000", 752)
    page1 += stock_header(764)
    page1 += [
        w("1234", 19, 38, 790),
        w("AB", 53, 60, 790),  # 短い先頭語は見かけ上コード列に落ちる→補正対象
        w("GOLD+ゴールド", 62, 118, 790),
        w("100", 134, 148, 790), w("500", 184, 198, 790), w("600", 213, 227, 790),
        w("60,000円", 248, 281, 790), w("0円", 298, 310, 790),
        w("10,000円", 318, 356, 790), w("20.00%", 374, 402, 790),
        w("架空", 411, 426, 790),
    ]
    page1 += [w("証券", 411, 426, 800)]
    # フッタ（私用領域文字つき）
    page1 += [w("ヘルプ・サポート", 496, 562, 815)]

    page2: list[Word] = []
    # 株式セクション続き: ヘッダ再出現（+20ptシフト→列スパン再計算の検証）
    page2 += stock_header(21, shift=20.0)
    page2 += [
        w("567A0", 39, 62, 55),
        w("テスト電機", 73, 130, 55),
        w("１０", 152, 168, 55),  # 全角数字
        w("2,000", 197, 218, 55), w("1,900", 226, 247, 55),
        w("19,000円", 262, 301, 55), w("0円", 318, 330, 55),
        w("▲1,000円", 336, 376, 55),  # 負の評価損益（▲表記）
        w("-5.00%", 390, 420, 55),
        w("架空", 431, 446, 55),
    ]
    page2 += [w("証券", 431, 446, 65)]
    # 投資信託
    page2 += heading("投資信託", 100)
    page2 += total_line("115,999", 115)
    page2 += fund_header(130)
    page2 += [
        w("架空インデックス", 19, 78, 148),
        w("10,000", 95, 121, 148), w("15,000", 145, 170, 148), w("16,000", 181, 206, 148),
        w("16,000円", 226, 260, 148), w("0円", 277, 289, 148),
        w("1,000円", 306, 335, 148), w("6.67%", 354, 378, 148),
        w("架空証券", 386, 416, 148),
    ]
    page2 += [w("ファンド", 19, 48, 158)]
    page2 += [  # 行内検算NG（5,000×20,000÷10000=10,000 ≠ 99,999）
        w("検算エラー投信", 19, 71, 177),
        w("5,000", 100, 121, 177), w("20,000", 145, 170, 177), w("20,000", 181, 206, 177),
        w("99,999円", 222, 260, 177), w("0円", 277, 289, 177),
        w("1円", 314, 335, 177), w("0.00%", 354, 378, 177),
        w("架空証券", 386, 416, 177),
    ]
    # 暗号資産
    page2 += heading("暗号資産", 250)
    page2 += total_line("500", 265)
    page2 += deposit_header(280)
    page2 += [w("BTC残高", 19, 48, 298), w("500円", 172, 192, 298), w("架空コイン", 200, 238, 298)]
    # 年金
    page2 += heading("年金", 350)
    page2 += total_line("120,000", 365)
    page2 += pension_header(380)
    page2 += [
        w("架空DCファンド", 19, 78, 398),
        w("100,000円", 110, 154, 398), w("120,000円", 164, 208, 398),
        w("20,000円", 220, 257, 398), w("20.00%", 285, 314, 398),
    ]
    page2 += [w("(確定拠出)", 19, 60, 408)]
    page2 += [w("ヘルプ・サポート", 496, 562, 815)]

    page3: list[Word] = []
    page3 += heading("ポイント", 50)
    page3 += total_line("1,400", 65)
    page3 += point_header(80)
    page3 += [
        w("架空ポ", 19, 34, 98), w("ポイント", 45, 75, 98),
        w("1,000ポイント", 119, 170, 98), w("1.00", 201, 217, 98),
        w("1,000円", 240, 269, 98), w("2027/01/31", 277, 320, 98),
        w("架空カード", 333, 378, 98),
    ]
    page3 += [w("イント", 19, 34, 108)]  # 名称の折返し断片
    page3 += [
        w("架空マイル", 19, 40, 127), w("マイル", 45, 68, 127),
        w("200マイル", 136, 170, 127), w("2.00", 201, 217, 127),
        w("400円", 247, 269, 127),
        w("架空カード", 333, 378, 127),
    ]
    # 割当不能行（直前レコードから離れすぎ・アンカーなし）
    page3 += [w("謎のデータ行", 19, 60, 177)]
    # 最終ページのフッタナビ（footer mode で無視される）
    page3 += [w("サービスについて", 71, 135, 584), w("サポート", 184, 216, 584), w("規約", 298, 314, 584)]
    page3 += [w("運営会社", 71, 103, 604), w("ヘルプ・サポート", 184, 248, 604), w("利用規約", 298, 330, 604)]
    page3 += [w("©", 204, 211, 700), w("Money", 214, 235, 700), w("Forward", 238, 265, 700)]
    page3 += [w("ヘルプ・サポート", 496, 562, 815)]

    return [page1, page2, page3]
